cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && python3 - <<'EOF'
import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
total=0
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H%x09%ci%x09%s',f'origin/friend/{b}'], text=True)
    for line in out.splitlines():
        # check full message for Friend-Message
        sha=line.split('\t')[0]
        msg=subprocess.check_output(['git','log','-1','--format=%B',sha], text=True)
        if 'Friend-Message: 1' in msg:
            # extract episode
            for l in msg.splitlines():
                if l.startswith('Episode:'):
                    ep=l.split(':',1)[1].strip()
            if ep=='S07/E12':
                total+=1
print('total S07/E12 friend messages:', total)
EOF
